with w as(select * from public.works where id=any(array[5185,1630,1852])),a as(select * from public.authors where id in(select author_id from w)) select jsonb_build_object('checked_at',clock_timestamp(),'works',(select jsonb_agg(to_jsonb(w) order by id) from w),'authors',(select jsonb_agg(to_jsonb(a) order by id) from a),'editions',(select jsonb_agg(to_jsonb(e) order by id) from public.editions e where work_id in(select id from w) or isbn_13=any(array['9789463821049','9789022576229','9789026346897']) or open_library_edition_id=any(array['OL41995844M','OL45876799M','OL61238876M'])),'descriptions',(select coalesce(jsonb_agg(to_jsonb(d) order by work_id,language),'[]') from public.catalog_work_descriptions d where work_id in(select id from w)),'metadata',(select coalesce(jsonb_agg(to_jsonb(m) order by edition_id),'[]') from public.catalog_edition_metadata m where work_id in(select id from w))) as preflight;
